&lt;li&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&lt;strong&gt;Tier 3 (other cities): &lt;/strong&gt;$130,190&amp;nbsp;&lt;span data-contrast=&quot;auto&quot;&gt; –&lt;/span&gt; $162,740&lt;/span&gt;&lt;/li&gt;
